    toggleVisibility: "Cambiar visibilidad"
  }
};

let currentLanguage = 'en';
let currentUser = null;

function changeLanguage() {
  currentLanguage = document.getElementById('language').value;
  updateTranslations();
}

function changeProfileLanguage() {
  currentLanguage = document.getElementById('profileLanguage').value;
  updateTranslations();
  if (currentUser) {
    db.collection('users').doc(currentUser.uid).update({
      language: currentLanguage
    });
  }
}

function updateTranslations() {
  const t = translations[currentLanguage];
  document.querySelectorAll('.logo').forEach(el => el.textContent = t.loginTitle);
  document.querySelector('.slogan').textContent = t.slogan;
  document.getElementById('email').placeholder = t.emailPlaceholder;
  document.getElementById('password').placeholder = t.passwordPlaceholder;
  document.getElementById('username').placeholder = t.usernamePlaceholder;
  document.querySelector('#anonymousProfile + span').textContent = t.anonymousProfile;
  document.querySelector('.signup-btn').innerHTML = `<i class="fas fa-user-plus"></i> ${t.signupButton}`;
  document.querySelector('.login-btn').innerHTML = `<i class="fas fa-sign-in-alt"></i> ${t.loginButton}`;
  document.querySelector('#editor h2').textContent = t.editorTitle;
  document.getElementById('mood').options[0].text = t.moodPlaceholder;
  document.getElementById('content').placeholder = t.contentPlaceholder;
  const privacySelect = document.getElementById('privacy');
  privacySelect.innerHTML = t.privacyOptions.map(opt => `<option value="${opt.split(' ')[0].toLowerCase()}">${opt}</option>`).join('');
  document.querySelector('.publish-btn').innerHTML = `<i class="fas fa-paper-plane"></i> ${t.publishButton}`;
  document.getElementById('bio').placeholder = t.bioPlaceholder;
  document.querySelector('#pagesWritten').nextSibling.textContent = t.pagesWritten;
  document.querySelector('#mostActiveDay').nextSibling.textContent = t.mostActiveDay;
  document.querySelector('.toggle-btn').innerHTML = `<i class="fas fa-eye"></i> ${t.toggleVisibility}`;
}

// Autenticazione
auth.onAuthStateChanged(user => {
  if (user) {
    currentUser = user;
    document.getElementById('login').classList.add('hidden');
    showHome();
    loadUserProfile();
    loadPosts();
  } else {
    currentUser = null;
    document.getElementById('login').classList.remove('hidden');
    document.getElementById('home').classList.add('hidden');
    document.getElementById('editor').classList.add('hidden');
    document.getElementById('profile').classList.add('hidden');
  }
});

function handleSignUp() {
  const email = document.getElementById('email').value;
  const password = document.getElementById('password').value;
  const username = document.getElementById('username').value;
  const anonymousProfile = document.getElementById('anonymousProfile').checked;

  auth.createUserWithEmailAndPassword(email, password)
    .then(userCredential => {
      const user = userCredential.user;
      return db.collection('users').doc(user.uid).set({
        username: username,
        anonymous: anonymousProfile,
        language: currentLanguage,
        bio: '',
        themeColor: '#FAF9F6',
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    })
    .catch(error => {
      alert(error.message);
    });
}

function handleLogin() {
  const email = document.getElementById('email').value;
  const password = document.getElementById('password').value;

  auth.signInWithEmailAndPassword(email, password)
    .catch(error => {
      alert(error.message);
    });
}

function handleLogout() {
  auth.signOut();
}

// Navigazione
function showHome() {
  document.getElementById('home').classList.remove('hidden');
  document.getElementById('editor').classList.add('hidden');
  document.getElementById('profile').classList.add('hidden');
  document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.nav-btn')[0].classList.add('active');
  loadPosts();
}

function showEditor() {
  document.getElementById('home').classList.add('hidden');
  document.getElementById('editor').classList.remove('hidden');
  document.getElementById('profile').classList.add('hidden');
  document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.nav-btn')[1].classList.add('active');
}

function showProfile() {
  document.getElementById('home').classList.add('hidden');
  document.getElementById('editor').classList.add('hidden');
  document.getElementById('profile').classList.remove('hidden');
  document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.nav-btn')[2].classList.add('active');
  loadProfileFeed();
}

// Gestione emoji
const picker = new EmojiButton();
const emojiButton = document.getElementById('emojiPicker');
picker.on('emoji', emoji => {
  document.getElementById('content').value += emoji.emoji;
});
document.getElementById('addEmoji').addEventListener('click', () => {
  picker.togglePicker(emojiButton);
});

// Gestione post
function publishPost() {
  const content = document.getElementById('content').value;
  const mood = document.getElementById('mood').value;
  const imageInput = document.getElementById('imageUpload');
  const privacy = document.getElementById('privacy').value;
  const anonymous = document.getElementById('anonymousProfile').checked;

  if (!content || !currentUser) return;

  let imageUrl = '';
  if (imageInput.files.length) {
    const file = imageInput.files[0];
    const storageRef = storage.ref(`images/${currentUser.uid}/${file.name}`);
    storageRef.put(file).then(snapshot => {
      snapshot.ref.getDownloadURL().then(url => {
        imageUrl = url;
        savePost(content, mood, privacy, anonymous, imageUrl);
      });
    });
  } else {
    savePost(content, mood, privacy, anonymous, imageUrl);
  }
}

function savePost(content, mood, privacy, anonymous, imageUrl) {
  const postContent = mood ? `${mood} ${content}` : content;
  db.collection('posts').add({
    userId: currentUser.uid,
    content: postContent,
    imageUrl: imageUrl,
    privacy: privacy,
    anonymous: anonymous,
    reactions: { '🌧️': 0, '☀️': 0, '❤️‍🩹': 0, '✨': 0, '🧘': 0 },
    createdAt: firebase.firestore.FieldValue.serverTimestamp()
  }).then(() => {
    document.getElementById('content').value = '';
    document.getElementById('imageUpload').value = '';
    document.getElementById('mood').value = '';
    showHome();
  });
}

function loadPosts() {
  const feed = document.getElementById('feed');
  feed.innerHTML = '';
  db.collection('posts').orderBy('createdAt', 'desc').get().then(snapshot => {
    snapshot.forEach(doc => {
      const post = doc.data();
      const postId = doc.id;
      db.collection('users').doc(post.userId).get().then(userDoc => {
        const user = userDoc.data();
        if (post.privacy === 'public' || (post.privacy === 'private' && !post.anonymous)) {
          const postDiv = document.createElement('div');
          postDiv.className = 'post';
          postDiv.innerHTML = `
            <div class="post-meta">${post.anonymous ? 'Anonymous' : user.username} • ${post.createdAt.toDate().toLocaleDateString()}</div>
            <p>${post.content}</p>
            ${post.imageUrl ? `<img src="${post.imageUrl}" alt="Post" class="post-image">` : ''}
            <div class="reactions">
              <button onclick="addReaction('${postId}', '🌧️')">🌧️</button>
              <button onclick="addReaction('${postId}', '☀️')">☀️</button>
              <button onclick="addReaction('${postId}', '❤️‍🩹')">❤️‍🩹</button>
              <button onclick="addReaction('${postId}', '✨')">✨</button>
              <button onclick="addReaction('${postId}', '🧘')">🧘</button>
            </div>
          `;
          feed.appendChild(postDiv);
        }
      });
    });
  });
}

function addReaction(postId, reactionType) {
  const postRef = db.collection('posts').doc(postId);
  postRef.get().then(doc => {
    const reactions = doc.data().reactions;
    reactions[reactionType]++;
    postRef.update({ reactions: reactions }).then(() => loadPosts());
  });
}

function loadProfileFeed() {
  const profileFeed = document.getElementById('profileFeed');
  profileFeed.innerHTML = '';
  db.collection('posts').where('userId', '==', currentUser.uid).orderBy('createdAt', 'desc').get().then(snapshot => {
    snapshot.forEach(doc => {
      const post = doc.data();
      const postDiv = document.createElement('div');
      postDiv.className = 'post';
      postDiv.innerHTML = `
        <div class="post-meta">${post.createdAt.toDate().toLocaleDateString()}</div>
        <p>${post.content}</p>
        ${post.imageUrl ? `<img src="${post.imageUrl}" alt="Post" class="post-image">` : ''}
      `;
      profileFeed.appendChild(postDiv);
    });
    updateProfile(snapshot.size);
  });
}

// Profilo
function loadUserProfile() {
  db.collection('users').doc(currentUser.uid).get().then(doc => {
    const user = doc.data();
    document.getElementById('profileUsername').textContent = `@${user.username}`;
    document.getElementById('bio').value = user.bio || '';
    document.getElementById('themeColor').value = user.themeColor || '#FAF9F6';
    document.getElementById('profileLanguage').value = user.language || 'en';
    changeProfileLanguage();
    document.querySelector('.profile-header').style.background = `linear-gradient(135deg, ${user.themeColor || '#FAF9F6'}, #E6E6FA)`;
    document.getElementById('anonymousProfile').checked = user.anonymous || false;
  });

  document.getElementById('bio').addEventListener('change', () => {
    db.collection('users').doc(currentUser.uid).update({
      bio: document.getElementById('bio').value
    });
  });
}

function updateProfile(postCount) {
  document.getElementById('pagesWritten').textContent = postCount;
  document.getElementById('mostActiveDay').textContent = 'N/A'; // Simulazione
}

function changeThemeColor() {
  const color = document.getElementById('themeColor').value;
  document.querySelector('.profile-header').style.background = `linear-gradient(135deg, ${color}, #E6E6FA)`;
  db.collection('users').doc(currentUser.uid).update({
    themeColor: color
  });
}

function toggleProfileVisibility() {
  const anonymous = document.getElementById('anonymousProfile').checked;
  db.collection('users').doc(currentUser.uid).update({
    anonymous: anonymous
  }).then(() => {
    alert(`Profile visibility toggled to ${anonymous ? 'Anonymous' : 'Visible'}`);
    loadPosts();
    loadProfileFeed();
  });
}

// Inizializza
updateTranslations();

