+    const [, tag] = item.split(':');
+    if (!tag) return acc;
+    const parts = tag.split('/');
+    if (!acc[parts[0]]) return acc;
+    acc[parts[0]].push(parts.pop());
+    return acc;
+  }, { categories: ['all'], types: [] });
